        var rank: [String: Int] = [:]
        for (index, key) in order.enumerated() where rank[key] == nil { rank[key] = index }
        let unsorted: [InventoryExample] = actions + billing + billingExperimental + charts + collaboration + collaborationExperimental + dataDisplay + dataGrid + feedback + files + filesExperimental + forms + foundations + geo + geoExperimental + identity + identityExperimental + intelligence + intelligenceExperimental + interaction + layout + layoutExperimental + navigation + overlays + overlaysExperimental + scheduling + schedulingExperimental + search + technical + technicalExperimental + typography + workflow + workflowExperimental
        return unsorted.enumerated().sorted { left, right in
            let a = rank[left.element.id + "|" + left.element.title] ?? Int.max
            let b = rank[right.element.id + "|" + right.element.title] ?? Int.max
            return a == b ? left.offset < right.offset : a < b
        }.map(\.element)
    }()
